import java.util.*;

class Solution {
    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, PriorityQueue<String>> adj = new HashMap<>();
        for (List<String> t : tickets) {
            adj.computeIfAbsent(t.get(0), k -> new PriorityQueue<>()).add(t.get(1));
        }
        List<String> route = new ArrayList<>();
        Deque<String> stack = new ArrayDeque<>();
        stack.push("JFK");
        while (!stack.isEmpty()) {
            PriorityQueue<String> dests = adj.get(stack.peek());
            if (dests == null || dests.isEmpty()) {
                route.add(stack.pop());          // no tickets left: finalize (post-order)
            } else {
                stack.push(dests.poll());        // use the smallest remaining ticket
            }
        }
        Collections.reverse(route);
        return route;
    }
}
